import React, { useEffect, useRef, useState } from 'react';
import Plotly from 'plotly.js-dist';
import './App.css';
import {
  client,
  useConfig,
  useElementColumns,
  useIncrementalElementData,
  useVariable,
} from "@sigmacomputing/plugin";

// Bright, cheerful 14-color categorical palette (petrol, magenta, coral,
// teal, gold, violet, orange, sky blue, brick, purple, green, blue, pink,
// tan), sized for up to ~14 distinct territories. Validated with the
// data-viz skill's palette validator: passes lightness band, chroma floor,
// colorblind-safe separation, and contrast on an adjacent-pair basis. With
// this many hues on a map, some pairs of territories can still land close
// in color if they happen to appear together (no qualitative set this size
// clears every possible pairing at once) -- the legend and per-zip hover
// tooltip are the backstop for that.
const COLOR_PALETTE = [
  '#1E85AC', '#C7519E', '#E85A3A', '#2FB79A', '#D9A62E', '#8A5FD9', '#E08830',
  '#2A9FC4', '#A8342E', '#A84FC7', '#4CAF50', '#3E6FD9', '#E8709E', '#A67A2E'
];

function hashIndex(name, modulus) {
  const str = String(name);
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash) % modulus;
}

// Assigns each name a palette color, hashed so a given name normally lands
// on the same color across refreshes. If two names hash to the same slot,
// the alphabetically-first one keeps it and the other is bumped to the next
// free slot -- so as long as there are no more distinct names than palette
// colors, every name currently on screen gets a distinct color, not just a
// probably-distinct one.
function assignColors(names) {
  const sorted = [...names].sort((a, b) => String(a).localeCompare(String(b)));
  const used = new Set();
  const colorByName = new Map();

  sorted.forEach(name => {
    let index = hashIndex(name, COLOR_PALETTE.length);
    let attempts = 0;
    while (used.has(index) && attempts < COLOR_PALETTE.length) {
      index = (index + 1) % COLOR_PALETTE.length;
      attempts++;
    }
    used.add(index);
    colorByName.set(name, COLOR_PALETTE[index]);
  });

  return colorByName;
}

// Abbreviated currency for the dot tooltip's Opp/Sales figures (e.g.
// "$57M", "$10M") -- these are large enough in practice that the full
// unabbreviated number would be harder to scan at a glance.
function formatCurrencyAbbrev(n) {
  if (!Number.isFinite(n)) return '$0';
  const sign = n < 0 ? '-' : '';
  const abs = Math.abs(n);
  if (abs >= 1e9) return `${sign}$${(abs / 1e9).toFixed(1).replace(/\.0$/, '')}B`;
  if (abs >= 1e6) return `${sign}$${(abs / 1e6).toFixed(1).replace(/\.0$/, '')}M`;
  if (abs >= 1e3) return `${sign}$${(abs / 1e3).toFixed(1).replace(/\.0$/, '')}K`;
  return `${sign}$${abs.toFixed(0)}`;
}

// Market share = MM Sales / MM Opp. Undefined (rather than a misleading
// 0%) when there's no Opp to take a share of.
function formatMarketShare(sales, opp) {
  if (!Number.isFinite(opp) || opp <= 0) return 'N/A';
  return `${Math.round((sales / opp) * 100)}%`;
}

// Zip codes come from Sigma in whatever format the source column happens to
// use -- a number (dropping a leading zero, e.g. "01001" -> 1001), a
// ZIP+4 like "89701-1234", or with stray whitespace. Normalizing to a plain
// 5-digit string before matching against the bundled dataset (which is
// keyed by clean 5-digit strings) means those don't silently fail to match
// and vanish from the map. The *filter* variable written back to Sigma
// still uses each row's original, unmodified zip value, so it keeps
// matching whatever format the user's own data uses elsewhere.
function normalizeZip(rawZip) {
  if (rawZip === null || rawZip === undefined) {
    return null;
  }
  const digits = String(rawZip).trim().match(/^\d+/);
  return digits ? digits[0].padStart(5, '0').slice(0, 5) : null;
}

// Some Sigma control variable types (e.g. a value selector bound to a
// column, as opposed to a button set) hand back an object like
// {value: "SA", ...} rather than a plain string. Reduce either shape to a
// plain string, so a label ends up empty or correct -- never literally
// "[object Object]" -- regardless of which control type happens to be
// wired to a given variable.
function variableLabel(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    if (typeof v.value === 'string') return v.value;
    if (typeof v.label === 'string') return v.label;
    // The shape actually seen from a Sigma value-selector control:
    // {name: "cMapLOB", defaultValue: {type: "text", value: "SA"}} --
    // note v.name here is the variable's own internal identifier, not
    // its selected value (confusingly, despite the name, defaultValue
    // holds the *current* value, not a separate fallback default).
    if (v.defaultValue && typeof v.defaultValue === 'object' && typeof v.defaultValue.value === 'string') {
      return v.defaultValue.value;
    }
  }
  return '';
}

// The heat map metric picker is a Sigma variable set by a control (e.g. a
// button set) the user builds elsewhere in the workbook -- it's expected to
// hold one of these three labels, matched case-insensitively. "MM Opp" wins
// on anything unrecognized (including the variable being unset), so the
// heat map still shows something reasonable before a control is wired up.
function metricKeyFromLabel(label) {
  const normalized = variableLabel(label).trim().toLowerCase();
  if (normalized === 'mm sales') return 'mmSales';
  if (normalized === 'mtgs') return 'mtgs';
  return 'mmOpp';
}

// Roughly centers and frames the continental US. Used as the fixed map view
// so the map doesn't re-center/re-zoom to fit whatever subset of data (e.g.
// after a lasso selection filters the source) happens to be loaded.
const DEFAULT_MAP_CENTER_LAT = 39.8283;
const DEFAULT_MAP_CENTER_LON = -98.5795;
const DEFAULT_MAP_ZOOM = 3.3;
const DEFAULT_HEATMAP_RADIUS = 20;

// The heat map is one dot per zip, built from concentric soft-edged circles
// rather than a kernel-density surface. Density fades every point from its
// center outward and shrinks low-value points, so low zips read as faint
// smudges; here every zip gets the same full-size green circle, and hotter
// zips grow warmer centers inside it -- yellow first, then orange, then red
// -- until the hottest are nearly all red. The blur between layers supplies
// the in-between shades (yellow-green, etc.).
//
// Each layer above the base appears once a zip's percentile (0..1) passes
// `start`, and grows linearly to `maxFraction` of the dot's radius by `end`.
// Drawn bottom to top.
const HEAT_LAYERS = [
  { color: 'rgb(0,200,120)', start: 0, end: 0, maxFraction: 1 },
  { color: 'rgb(255,221,0)', start: 0.2, end: 0.6, maxFraction: 0.9 },
  { color: 'rgb(255,140,0)', start: 0.45, end: 0.8, maxFraction: 0.85 },
  { color: 'rgb(220,20,20)', start: 0.6, end: 1, maxFraction: 0.8 }
];
const HEAT_DOT_OPACITY = 0.85;
// MapLibre circle-blur, as a fraction of the radius -- softens each layer's
// edge so the colors blend into a gradient instead of hard bands, and
// overlapping dots blend instead of looking like stickers.
const HEAT_DOT_BLUR = 0.4;

// Percentile (0..1) of each weight, by rank among all the weights passed
// in. Rank-based so a handful of huge zips can't push everything else down
// to all-green. Ties share their first-ranked occurrence's percentile, so
// equal values always look the same.
function heatPercentiles(weights) {
  if (weights.length === 1) return [1];
  const sorted = [...weights].sort((a, b) => a - b);
  const firstRank = new Map();
  sorted.forEach((w, i) => {
    if (!firstRank.has(w)) firstRank.set(w, i);
  });
  return weights.map(w => firstRank.get(w) / (sorted.length - 1));
}

// How much of the dot's radius (0..maxFraction) a layer covers at a given
// percentile.
function heatLayerFraction(layer, percentile) {
  if (layer.end <= layer.start) return percentile >= layer.start ? layer.maxFraction : 0;
  const t = (percentile - layer.start) / (layer.end - layer.start);
  return Math.max(0, Math.min(1, t)) * layer.maxFraction;
}

// A heat dot's radius is a constant number of screen pixels, which
// covers a shrinking geographic area as you zoom in -- but not fast
// enough to stay within a single zip once you're zoomed in past a
// regional view, so a zip's heat visibly bleeds into its neighbors'.
// Below this zoom, the configured radius is used as-is (a wide, blended
// look is what you want at state/national zoom). Above it, radius is
// halved every 2 zoom levels on top of that natural shrinkage, so heat
// stays roughly confined to the zip it belongs to once you're zoomed in
// far enough to see individual zip shapes.
const HEATMAP_RADIUS_REFERENCE_ZOOM = 8;
const HEATMAP_RADIUS_MIN = 4;

function radiusForZoom(baseRadius, zoom) {
  if (!Number.isFinite(zoom) || zoom <= HEATMAP_RADIUS_REFERENCE_ZOOM) return baseRadius;
  const zoomDelta = zoom - HEATMAP_RADIUS_REFERENCE_ZOOM;
  return Math.max(HEATMAP_RADIUS_MIN, baseRadius / Math.pow(2, zoomDelta / 2));
}

// Zip code (ZCTA) boundary + centroid lookup, bundled with the plugin so
// Sigma only needs to supply a zip code and a territory per row -- no
// latitude/longitude columns required. See README.md for the dataset's
// full lineage (Census cartographic boundary file, plus a GeoNames-derived
// fallback for zip codes with no ZCTA at all).
const ZCTA_DATA_URL = `${process.env.PUBLIC_URL}/data/zcta.json`;

// Only the outer ring of each polygon is used (holes are ignored) -- at this
// simplification level ZCTA shapes essentially never have meaningful holes.
function outerRings(geometry) {
  if (!geometry) return [];
  if (geometry.type === 'Polygon') {
    return [geometry.coordinates[0]];
  }
  if (geometry.type === 'MultiPolygon') {
    return geometry.coordinates.map(polygon => polygon[0]);
  }
  return [];
}

// Some zips in the bundled dataset have a centroid but no boundary polygon
// (e.g. PO-box-only or single-organization zip codes with no ZCTA at all).
// Without this, those zips would render as an invisible gap in an otherwise
// filled territory even though they're valid rows in the source data. Draw
// a small square centered on the centroid instead, so there's at least a
// visible patch of color rather than an unexplained hole.
const FALLBACK_SHAPE_RADIUS_DEG = 0.025;

function ringsForZip(entry) {
  if (entry.rings.length) {
    return entry.rings;
  }
  const { lat, lon } = entry;
  const r = FALLBACK_SHAPE_RADIUS_DEG;
  return [[
    [lon - r, lat - r],
    [lon - r, lat + r],
    [lon + r, lat + r],
    [lon + r, lat - r],
    [lon - r, lat - r]
  ]];
}

// Plotly's scattermap exposes no attribute for MapLibre's circle-blur, so
// the heat dots' soft edge gets set directly on the circle layer Plotly
// manages. That reaches past Plotly's public API, so every hop is guarded:
// if a Plotly upgrade moves any of this, the cost should be hard-edged dots,
// never a thrown error. No regex fallback on the layer id here -- the dot
// trace is also a scattermap circle layer, and blurring it by mistake
// would be worse than not blurring at all.
function applyHeatDotBlur(graphDiv, heatmapTraceIndices) {
  try {
    const fullLayout = graphDiv && graphDiv._fullLayout;
    const subplot = fullLayout && fullLayout.map && fullLayout.map._subplot;
    const map = subplot && subplot.map;
    if (!map || typeof map.setPaintProperty !== 'function') return;

    const fullData = graphDiv._fullData;
    heatmapTraceIndices.forEach(i => {
      const trace = fullData && fullData[i];
      const layerId = trace && trace.uid ? `plotly-trace-layer-${trace.uid}-circle` : null;
      if (!layerId || !map.getLayer(layerId)) return;
      map.setPaintProperty(layerId, 'circle-blur', HEAT_DOT_BLUR);
    });
  } catch (err) {
    // Non-fatal -- the heat dots still draw, just with hard edges.
  }
}

// Token-free basemaps (Carto / OpenStreetMap tiles via Plotly's MapLibre
// engine) -- no Mapbox account or access token required.
const DEFAULT_MAP_STYLE = 'carto-positron';
const VALID_MAP_STYLES = [
  'carto-positron',
  'carto-positron-nolabels',
  'carto-darkmatter',
  'carto-darkmatter-nolabels',
  'carto-voyager',
  'carto-voyager-nolabels',
  'open-street-map',
  'white-bg'
];

client.config.configureEditorPanel([
  { type: "element", name: "source" },
  { type: "column", name: "zipcode", source: "source", allowMultiple: false },
  { type: "column", name: "territory", source: "source", allowMultiple: false },
  { type: "column", name: "channel", source: "source", allowMultiple: false },
  { type: "column", name: "fw", source: "source", allowMultiple: false },
  { type: "column", name: "city", source: "source", allowMultiple: false },
  { type: "column", name: "state", source: "source", allowMultiple: false },
  { type: "column", name: "mmOpp", source: "source", allowMultiple: false },
  { type: "column", name: "mmSales", source: "source", allowMultiple: false },
  { type: "column", name: "mtgs", source: "source", allowMultiple: false },
  { type: "column", name: "tooltipFields", source: "source", allowMultiple: true },
  { type: "variable", name: "filterZipcode" },
  { type: "variable", name: "heatmapMetric" },
  { type: "variable", name: "productLob" },
  { name: "Variables", type: 'group' },
  { name: 'ShowLegend', source: "Variables", type: "toggle", defaultValue: true },
  { name: 'ShowHeatmap', source: "Variables", type: "toggle", defaultValue: false },
  { name: 'HeatmapRadius', source: "Variables", type: 'text', defaultValue: String(DEFAULT_HEATMAP_RADIUS) },
  { name: 'MapStyle', source: "Variables", type: 'text', defaultValue: DEFAULT_MAP_STYLE },
  { name: 'MapCenterLat', source: "Variables", type: 'text', defaultValue: String(DEFAULT_MAP_CENTER_LAT) },
  { name: 'MapCenterLon', source: "Variables", type: 'text', defaultValue: String(DEFAULT_MAP_CENTER_LON) },
  { name: 'MapZoom', source: "Variables", type: 'text', defaultValue: String(DEFAULT_MAP_ZOOM) },
]);

function App() {
  const config = useConfig();
  // useElementData caps out at 25,000 rows and silently truncates anything
  // past that -- a source with multiple rows per zip (one per channel,
  // product line, etc.) can run past that easily, so
  // useIncrementalElementData (no row cap, fetched in chunks via
  // loadMoreData) is used instead to make sure every row makes it through.
  const [sigmaData, loadMoreData, dataInfo] = useIncrementalElementData(config.source);
  const columns = useElementColumns(config.source);
  // The current value is never read back -- this variable is write-only
  // from the plugin's side (set on lasso-select, cleared on deselect).
  const [, setFilterZipcode] = useVariable(config.filterZipcode);
  // Set by a Sigma control (e.g. a button set or a value selector) built
  // elsewhere in the workbook -- the plugin only reads this, it never
  // writes it. Reduced to a plain string immediately: some control types
  // hand back an object here rather than a string, and that object can be
  // a fresh reference on every render even when its value hasn't changed
  // -- using the raw value as an effect dependency further down would then
  // bypass the render debounce the same way an unstable config/columns
  // reference did before.
  const [heatmapMetricRaw] = useVariable(config.heatmapMetric);
  const heatmapMetricLabel = variableLabel(heatmapMetricRaw);
  // Read-only, same idea: whichever Product LOB label (e.g. "SA", "FA") a
  // Sigma control elsewhere in the workbook currently has selected. The
  // source data is already filtered to that LOB upstream -- this is only
  // used to label the dot tooltip's metrics correctly.
  const [productLobRaw] = useVariable(config.productLob);
  const productLobLabel = variableLabel(productLobRaw);
  const [prevSigmaData, setPrevSigmaData] = useState(null);
  const prevColumnsRef = useRef(null);
  // Tracks the labels the redraw below last actually used, so a control
  // (heatmapMetric/productLob) that resolves asynchronously -- landing
  // after sigmaData/columns have already settled once -- still triggers a
  // redraw instead of leaving the plot permanently stuck on whatever those
  // labels were (often empty) the one time the sigmaData/columns check
  // below happened to pass.
  const prevHeatmapMetricLabelRef = useRef(null);
  const prevProductLobLabelRef = useRef(null);
  const [zctaByZip, setZctaByZip] = useState(null);
  const [renderTrigger, setRenderTrigger] = useState(0);
  const renderDebounceRef = useRef(null);
  // Tracks the viewer's current pan/zoom (updated live via plotly_relayout
  // below) so a redraw triggered by a data change re-applies whatever view
  // the viewer is currently looking at, instead of snapping back to the
  // configured default every time -- otherwise manually zooming in gets
  // undone by the next redraw, which can happen as often as the source
  // data changes (e.g. every zip reassignment in a live editing tool).
  const currentViewRef = useRef(null);
  // The configured (or built-in default) view, refreshed on every redraw,
  // so the reset button has somewhere to go back to.
  const defaultViewRef = useRef(null);
  // Active map tool ('lasso' or 'pan'), driven by the buttons at the bottom
  // right. The ref (not just state) feeds the layout below so a data-driven
  // redraw keeps whichever tool the viewer picked instead of resetting it.
  const dragModeRef = useRef('lasso');
  const [dragMode, setDragMode] = useState('lasso');
  const lastSeenContentKeyRef = useRef(null);

  // Keep requesting the next chunk until the host reports every row has
  // been delivered.
  useEffect(() => {
    if (config.source && !dataInfo.isComplete) {
      loadMoreData();
    }
  }, [config.source, dataInfo.isComplete, dataInfo.rowCount, loadMoreData]);

  // Coalesces a burst of rapid source updates (e.g. while a user is
  // actively dragging zips between territories in a reassignment tool)
  // into a single redraw once things settle, instead of rebuilding the
  // whole map on every single intermediate tick -- which was fast enough
  // to keep the map stuck flashing between rendered and its brief
  // "no tiles yet" state, or never finishing at all.
  useEffect(() => {
    // Gated by content, not just sigmaData/columns/config changing
    // reference: the SDK can hand back new objects for all three on
    // internal ticks even when nothing really changed (useConfig() in
    // particular returns a fresh object every call), and resetting the
    // timer on every one of those (rather than only on real changes)
    // could keep deferring the render indefinitely as long as those ticks
    // keep arriving faster than the debounce delay.
    const contentKey = JSON.stringify([sigmaData, columns, config]);
    if (contentKey === lastSeenContentKeyRef.current) {
      return;
    }
    lastSeenContentKeyRef.current = contentKey;

    if (renderDebounceRef.current) {
      clearTimeout(renderDebounceRef.current);
    }
    renderDebounceRef.current = setTimeout(() => {
      setRenderTrigger(t => t + 1);
    }, 250);
    return () => clearTimeout(renderDebounceRef.current);
  }, [sigmaData, columns, config]);

  useEffect(() => {
    let cancelled = false;

    // no-store: this file has changed several times during development and
    // an iframe-embedded plugin can end up pinned to a stale cached copy
    // (browser or Sigma's own resource cache) longer than the server's
    // Cache-Control max-age would suggest -- bypass HTTP caching entirely
    // rather than rely on revalidation.
    fetch(ZCTA_DATA_URL, { cache: 'no-store' })
      .then(res => res.json())
      .then(geojson => {
        if (cancelled) return;

        const byZip = new Map();
        geojson.features.forEach(feature => {
          const { zip, lat, lon } = feature.properties;
          byZip.set(zip, {
            rings: outerRings(feature.geometry),
            lat,
            lon
          });
        });

        setZctaByZip(byZip);
      })
      .catch(err => {
        console.error('Failed to load zip code boundary data', err);
      });

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const updatePlotSize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      Plotly.relayout('myDiv', { width: width, height: height });
    };

    window.addEventListener('resize', updatePlotSize);

    return () => {
      window.removeEventListener('resize', updatePlotSize);
    };
  }, []);

  useEffect(() => {
    // Compared by content (JSON.stringify), not object identity: the SDK
    // can hand back a new sigmaData/columns object on every internal update
    // even when nothing actually changed, and gating on reference equality
    // instead would re-run the full Plotly.newPlot redraw on every one of
    // those ticks -- visible as the whole map flashing/rebuilding in a loop.
    const columnsKey = JSON.stringify(columns);
    if (
      zctaByZip &&
      sigmaData &&
      (JSON.stringify(sigmaData) !== JSON.stringify(prevSigmaData) ||
        columnsKey !== prevColumnsRef.current ||
        heatmapMetricLabel !== prevHeatmapMetricLabelRef.current ||
        productLobLabel !== prevProductLobLabelRef.current)
    ) {
      setPrevSigmaData(sigmaData);
      prevColumnsRef.current = columnsKey;
      prevHeatmapMetricLabelRef.current = heatmapMetricLabel;
      prevProductLobLabelRef.current = productLobLabel;

      const graphDiv = document.getElementById('myDiv');

      // If a lasso selection is active when this effect re-runs (e.g. a
      // legitimate data refresh arrives while the user has zips
      // selected), capture which zips were selected before rebuilding the
      // plot below, so the selection can be re-applied by zip identity
      // afterward instead of just disappearing.
      let previouslySelectedZips = null;
      if (graphDiv && graphDiv.data) {
        const prevDotTrace = graphDiv.data.find(t => t.name === 'Zip codes');
        if (prevDotTrace && Array.isArray(prevDotTrace.selectedpoints) && prevDotTrace.selectedpoints.length) {
          previouslySelectedZips = new Set(
            prevDotTrace.selectedpoints.map(i => prevDotTrace.customdata[i])
          );
        }
      }

      const zip = sigmaData[config.zipcode];
      const territory = sigmaData[config.territory];

      if (!zip || !territory) {
        return;
      }

      // The channel/metric/tooltip columns are all optional -- without
      // them the plugin still works exactly as before (one shape+dot per
      // zip, no per-channel totals, no heat map, a sparser dot tooltip).
      const channelCol = config.channel ? sigmaData[config.channel] : null;
      const fwCol = config.fw ? sigmaData[config.fw] : null;
      const cityCol = config.city ? sigmaData[config.city] : null;
      const stateCol = config.state ? sigmaData[config.state] : null;
      const mmOppCol = config.mmOpp ? sigmaData[config.mmOpp] : null;
      const mmSalesCol = config.mmSales ? sigmaData[config.mmSales] : null;
      const mtgsCol = config.mtgs ? sigmaData[config.mtgs] : null;

      const normalizedZip = zip.map(normalizeZip);

      // A zip code can appear on many rows (one per channel, product line,
      // etc.), so every row is first folded into one aggregate per zip:
      // its territory, plus MM Opp / MM Sales / Mtgs summed per channel
      // and overall (the overall totals drive the heat map; the
      // per-channel totals drive the dot tooltip). Zip codes with no entry
      // in the bundled dataset are collected separately for the
      // "not shown" note -- as a set, so a zip missing across many rows
      // is still counted once, matching what the note says.
      const zipAgg = new Map();
      const unmatchedZips = new Set();

      zip.forEach((rawZip, index) => {
        const normZip = normalizedZip[index];
        if (!zctaByZip.has(normZip)) {
          unmatchedZips.add(rawZip);
          return;
        }

        if (!zipAgg.has(normZip)) {
          zipAgg.set(normZip, {
            rawZip,
            firstIndex: index,
            territory: territory[index],
            fw: fwCol ? fwCol[index] : null,
            city: cityCol ? cityCol[index] : null,
            state: stateCol ? stateCol[index] : null,
            channelTotals: new Map(),
            totals: { mmOpp: 0, mmSales: 0, mtgs: 0 }
          });
        }
        const agg = zipAgg.get(normZip);

        const opp = mmOppCol ? Number(mmOppCol[index]) || 0 : 0;
        const sales = mmSalesCol ? Number(mmSalesCol[index]) || 0 : 0;
        const mtg = mtgsCol ? Number(mtgsCol[index]) || 0 : 0;

        agg.totals.mmOpp += opp;
        agg.totals.mmSales += sales;
        agg.totals.mtgs += mtg;

        const ch = channelCol ? channelCol[index] : null;
        if (ch !== null && ch !== undefined && ch !== '') {
          if (!agg.channelTotals.has(ch)) {
            agg.channelTotals.set(ch, { mmOpp: 0, mmSales: 0, mtgs: 0 });
          }
          const chTotal = agg.channelTotals.get(ch);
          chTotal.mmOpp += opp;
          chTotal.mmSales += sales;
          chTotal.mtgs += mtg;
        }
      });

      const unmappedCount = unmatchedZips.size;
      if (unmappedCount > 0) {
        console.warn(
          `Zip Code Lasso Map: ${unmappedCount} distinct zip value(s) did not match the boundary dataset. First 20:`,
          Array.from(unmatchedZips).slice(0, 20)
        );
      }

      // Group unique zips by territory for the filled shapes.
      const zipsByTerritory = new Map();
      zipAgg.forEach((agg, normZip) => {
        const t = agg.territory;
        if (!zipsByTerritory.has(t)) {
          zipsByTerritory.set(t, []);
        }
        zipsByTerritory.get(t).push(normZip);
      });

      const sortedTerritories = Array.from(zipsByTerritory.keys()).sort((a, b) =>
        String(a).localeCompare(String(b))
      );
      const colorByTerritory = assignColors(sortedTerritories);

      const tooltipFieldIds = Array.isArray(config.tooltipFields) ? config.tooltipFields : [];

      // Per-territory tooltip text (first non-empty tooltipFields value
      // found among that territory's rows) -- shared by every zip shape
      // in the territory.
      const tooltipTextByTerritory = new Map();
      sortedTerritories.forEach(t => {
        const zipsInTerritory = zipsByTerritory.get(t);
        const firstIndex = zipAgg.get(zipsInTerritory[0]).firstIndex;
        const tooltipLines = [`<b>${t}</b>`];
        tooltipFieldIds.forEach(fieldId => {
          const columnValues = sigmaData[fieldId];
          if (!columnValues) return;
          const value = columnValues[firstIndex];
          if (value === null || value === undefined || value === '') return;
          const label = (columns[fieldId] && columns[fieldId].name) || fieldId;
          tooltipLines.push(`${label}: ${value}`);
        });
        tooltipTextByTerritory.set(t, tooltipLines.join('<br>'));
      });

      // Territory shapes are drawn as a single choroplethmap trace
      // rather than one scattermap fill-to-self trace per territory.
      // Plotly's map engine hardcodes its layer stacking order --
      // choroplethmap always below densitymap always below
      // scattermap, regardless of trace array order -- so this is the
      // only way to get the heat map to render on top of the territory
      // coloring instead of underneath it.
      const territoryIndex = new Map(sortedTerritories.map((t, i) => [t, i]));
      const territoryCount = sortedTerritories.length;

      const choroplethFeatures = [];
      const choroplethLocations = [];
      const choroplethZ = [];
      const choroplethText = [];

      zipAgg.forEach((agg, normZip) => {
        const rings = ringsForZip(zctaByZip.get(normZip));
        choroplethFeatures.push({
          type: 'Feature',
          id: normZip,
          geometry: { type: 'MultiPolygon', coordinates: rings.map(ring => [ring]) }
        });
        choroplethLocations.push(normZip);
        // +0.5 lands each zip solidly inside its territory's color band
        // rather than exactly on the boundary between two bands.
        choroplethZ.push(territoryIndex.get(agg.territory) + 0.5);
        choroplethText.push(tooltipTextByTerritory.get(agg.territory));
      });

      // A flat, stepped colorscale so each territory's index band renders
      // as that territory's exact assigned color, not a gradient.
      const territoryColorscale = [];
      sortedTerritories.forEach((t, i) => {
        const color = colorByTerritory.get(t);
        territoryColorscale.push([i / territoryCount, color]);
        territoryColorscale.push([(i + 1) / territoryCount, color]);
      });

      const choroplethTrace = territoryCount > 0 ? {
        type: 'choroplethmap',
        geojson: { type: 'FeatureCollection', features: choroplethFeatures },
        locations: choroplethLocations,
        z: choroplethZ,
        zmin: 0,
        zmax: territoryCount,
        colorscale: territoryColorscale,
        showscale: false,
        marker: { opacity: 0.2, line: { color: 'rgba(0,0,0,0.8)', width: 0.75 } },
        text: choroplethText,
        hoverinfo: 'text',
        showlegend: false
      } : null;

      // Dummy invisible point traces purely to give each territory its
      // own legend swatch -- choroplethmap only supports a single
      // continuous colorscale legend, not one per category.
      const legendTraces = sortedTerritories.map(t => ({
        type: 'scattermap',
        mode: 'markers',
        lon: [DEFAULT_MAP_CENTER_LON],
        lat: [DEFAULT_MAP_CENTER_LAT],
        marker: { size: 8, color: colorByTerritory.get(t), opacity: 0 },
        name: t,
        showlegend: true,
        hoverinfo: 'skip'
      }));

      // Single trace of centroid dots across all zips -- this is what
      // actually receives lasso/box selection (Plotly doesn't support
      // lasso-selecting filled map shapes), colored to match each zip's
      // territory fill. Its hover shows the per-channel MM Opp/MM
      // Sales/Mtgs breakdown when those columns are configured.
      const dotLons = [];
      const dotLats = [];
      const dotColors = [];
      const dotZips = [];
      const dotLabels = [];

      // Opp/Sales/Mkt Share are labeled with whatever Product LOB is
      // currently selected (e.g. "SA MM Opp", "FA MM Opp") -- the
      // underlying totals are already scoped to that LOB, since the source
      // is filtered upstream by the same Sigma control.
      const lobPrefix = productLobLabel ? `${productLobLabel} ` : '';

      zipAgg.forEach((agg, normZip) => {
        const entry = zctaByZip.get(normZip);
        dotLons.push(entry.lon);
        dotLats.push(entry.lat);
        dotColors.push(colorByTerritory.get(agg.territory));
        dotZips.push(agg.rawZip);

        // Header: "{FW} | {Territory}" then "{City}, {State}" -- FW and
        // territory are the rep and their assigned territory for this zip;
        // city/state are omitted if those columns aren't configured.
        const headerParts = [];
        if (agg.fw) headerParts.push(agg.fw);
        headerParts.push(agg.territory);
        const cityState = [agg.city, agg.state].filter(Boolean).join(', ');

        const lines = [headerParts.join(' | ')];
        if (cityState) lines.push(cityState);
        if (mmOppCol) lines.push(`${lobPrefix}MM Opp: ${formatCurrencyAbbrev(agg.totals.mmOpp)}`);
        if (mmSalesCol) lines.push(`${lobPrefix}MM Sales: ${formatCurrencyAbbrev(agg.totals.mmSales)}`);
        if (mmOppCol && mmSalesCol) {
          lines.push(`${lobPrefix}MM Mkt Share: ${formatMarketShare(agg.totals.mmSales, agg.totals.mmOpp)}`);
        }
        dotLabels.push(lines.join('<br>'));
      });

      const dotTrace = {
        type: 'scattermap',
        mode: 'markers',
        name: 'Zip codes',
        lon: dotLons,
        lat: dotLats,
        marker: { size: 4, color: dotColors, opacity: 0.1 },
        customdata: dotZips,
        text: dotLabels,
        hovertemplate: '%{text}<extra></extra>',
        showlegend: false
      };

      // Fixed map view (defaults to framing the continental US) so the map
      // doesn't jump to fit whatever subset of data is currently loaded --
      // but once the viewer has actually panned/zoomed, that becomes the
      // baseline instead (see currentViewRef above), so a later redraw
      // doesn't snap back to the configured default underneath them.
      const parsedCenterLat = parseFloat(config.MapCenterLat);
      const parsedCenterLon = parseFloat(config.MapCenterLon);
      const parsedZoom = parseFloat(config.MapZoom);

      const configCenterLat = Number.isFinite(parsedCenterLat) ? parsedCenterLat : DEFAULT_MAP_CENTER_LAT;
      const configCenterLon = Number.isFinite(parsedCenterLon) ? parsedCenterLon : DEFAULT_MAP_CENTER_LON;
      const configZoom = Number.isFinite(parsedZoom) ? parsedZoom : DEFAULT_MAP_ZOOM;
      defaultViewRef.current = { lat: configCenterLat, lon: configCenterLon, zoom: configZoom };

      const currentView = currentViewRef.current;
      const centerLat = currentView ? currentView.lat : configCenterLat;
      const centerLon = currentView ? currentView.lon : configCenterLon;
      const zoom = currentView ? currentView.zoom : configZoom;

      // Optional heat map layer, drawn on top of the territory shapes. One
      // dot per zip with a positive total (summed across all channels) for
      // whichever of MM Opp / MM Sales / Mtgs the heatmapMetric Sigma
      // variable currently selects, its warm center sized by that total's
      // percentile. heatmapFractions[i] holds heatmapTraces[i]'s per-dot
      // radius fractions, for re-sizing on zoom.
      const heatmapTraces = [];
      const heatmapFractions = [];
      let baseHeatmapRadius = DEFAULT_HEATMAP_RADIUS;
      if (config.ShowHeatmap && (mmOppCol || mmSalesCol || mtgsCol)) {
        const metricKey = metricKeyFromLabel(heatmapMetricLabel);
        const heatPoints = [];

        zipAgg.forEach((agg, normZip) => {
          const weight = agg.totals[metricKey];
          if (!weight || weight <= 0) return;
          const entry = zctaByZip.get(normZip);
          heatPoints.push({ lon: entry.lon, lat: entry.lat, weight });
        });

        if (heatPoints.length) {
          const parsedRadius = parseFloat(config.HeatmapRadius);
          baseHeatmapRadius = Number.isFinite(parsedRadius) ? parsedRadius : DEFAULT_HEATMAP_RADIUS;
          // Ascending, so within a layer the hotter dot draws on top.
          heatPoints.sort((a, b) => a.weight - b.weight);
          const percentiles = heatPercentiles(heatPoints.map(p => p.weight));
          const dotSize = 2 * radiusForZoom(baseHeatmapRadius, zoom);

          // One trace per HEAT_LAYERS entry, each holding only the zips hot
          // enough to show that layer. Every zip's yellow sits above every
          // zip's green, and so on, so a hot zip's center is never buried
          // under a cooler neighbor's edge.
          HEAT_LAYERS.forEach(layer => {
            const lons = [];
            const lats = [];
            const fractions = [];
            heatPoints.forEach((p, i) => {
              const fraction = heatLayerFraction(layer, percentiles[i]);
              if (fraction <= 0) return;
              lons.push(p.lon);
              lats.push(p.lat);
              fractions.push(fraction);
            });
            if (!lons.length) return;
            heatmapTraces.push({
              type: 'scattermap',
              mode: 'markers',
              lon: lons,
              lat: lats,
              marker: {
                size: fractions.map(f => f * dotSize),
                color: layer.color,
                opacity: HEAT_DOT_OPACITY
              },
              // Same opacity either way, so a lasso selection (which only
              // ever targets the zip dots) doesn't dim the heat map too.
              selected: { marker: { opacity: HEAT_DOT_OPACITY } },
              unselected: { marker: { opacity: HEAT_DOT_OPACITY } },
              showlegend: false,
              hoverinfo: 'skip'
            });
            heatmapFractions.push(fractions);
          });
        }
      }

      // The heat dots go before the zip dots: both are scattermap, which
      // stack in trace order, and the zip dots need to stay on top to keep
      // their tooltip and lasso selection.
      const plotData = [
        ...(choroplethTrace ? [choroplethTrace] : []),
        ...legendTraces,
        ...heatmapTraces,
        dotTrace
      ];
      const heatmapTraceIndices = heatmapTraces.map(t => plotData.indexOf(t));
      const dotTraceIndex = plotData.indexOf(dotTrace);
      const choroplethTraceIndex = choroplethTrace ? plotData.indexOf(choroplethTrace) : null;

      // Saved workbooks may still hold an old Mapbox style name (e.g.
      // "light"), so anything outside the token-free list falls back.
      const mapStyle = VALID_MAP_STYLES.includes(config.MapStyle) ? config.MapStyle : DEFAULT_MAP_STYLE;

      const layout = {
        dragmode: dragModeRef.current,
        map: {
          center: {
            lat: centerLat,
            lon: centerLon
          },
          domain: {
            x: [0, 1],
            y: [0, 1]
          },
          style: mapStyle,
          zoom: zoom
        },
        margin: {
          r: 0,
          t: 0,
          b: 0,
          l: 0,
          pad: 0
        },
        paper_bgcolor: '#191A1A',
        plot_bgcolor: '#191A1A',
        autosize: true,
        legend: {
          x: 0.01,
          y: 0.98,
          bgcolor: 'rgba(0,0,0,0.5)',
          font: { color: 'white' },
          visible: config.ShowLegend
        },
        annotations: unmappedCount > 0 ? [{
          text: `${unmappedCount} zip code${unmappedCount === 1 ? '' : 's'} not shown`,
          showarrow: false,
          xref: 'paper',
          yref: 'paper',
          x: 0.99,
          y: 0.02,
          // Clear of the map control buttons in the bottom-right corner.
          xshift: -48,
          xanchor: 'right',
          yanchor: 'bottom',
          font: { size: 11, color: '#ccc' },
          bgcolor: 'rgba(0,0,0,0.5)'
        }] : []
      };

      // Plotly.react (not Plotly.newPlot) patches the existing plot in
      // place instead of tearing down and recreating the whole MapLibre GL
      // WebGL context every time this effect re-runs. With a data source
      // that updates frequently (e.g. while a user is actively dragging
      // zips around in a reassignment tool), newPlot's full teardown
      // couldn't keep up -- each rebuild has to reload map tiles from
      // scratch, so a fast stream of updates kept the map stuck showing
      // that brief "no tiles yet" black state instead of ever finishing.
      Plotly.react('myDiv', plotData, layout, {
        // Plotly's own toolbar is hidden -- the pan/lasso and zoom buttons
        // at the bottom right replace it. Scroll-wheel zoom stays on.
        displayModeBar: false,
        scrollZoom: true
      }).then(() => {
        if (heatmapTraces.length) {
          applyHeatDotBlur(document.getElementById('myDiv'), heatmapTraceIndices);
        }
      });

      // Re-apply the selection captured above (by zip identity, not
      // index -- the new dot order may differ) so a data refresh that
      // happens to land while zips are selected doesn't just wipe the
      // selection out from under the user.
      if (previouslySelectedZips) {
        const newSelectedIndices = dotZips
          .map((z, i) => (previouslySelectedZips.has(z) ? i : null))
          .filter(i => i !== null);
        if (newSelectedIndices.length) {
          Plotly.restyle(graphDiv, { selectedpoints: [newSelectedIndices] }, [dotTraceIndex]);
        }
      }

      // Plotly.newPlot re-draws the plot but doesn't clear listeners
      // previously registered on this same div -- without this, every time
      // this effect re-runs (e.g. on a legitimate data/config change) it'd
      // stack another copy of each handler below on top of the old ones,
      // so a single lasso selection would fire setFilterZipcode multiple
      // times over with increasingly stale closures.
      graphDiv.removeAllListeners();

      // Resets Plotly's own selected/unselected styling on every
      // selectable trace -- the dots (the actual selection target) and,
      // as a backstop for older data where the selected/unselected
      // opacity override above might not apply, the territory shapes.
      function clearVisualSelection() {
        const indices = [dotTraceIndex, choroplethTraceIndex].filter(i => i !== null);
        Plotly.restyle(graphDiv, { selectedpoints: indices.map(() => null) }, indices);
      }

      graphDiv.on('plotly_selected', function (eventData) {
        const selectedZipcodes = eventData && eventData.points
          ? eventData.points
            .map(pt => pt.customdata)
            .filter(z => z !== undefined && z !== null)
          : [];

        const uniqueSelectedZipcodes = Array.from(new Set(selectedZipcodes));

        if (uniqueSelectedZipcodes.length) {
          setFilterZipcode(uniqueSelectedZipcodes.join(","));
        } else {
          // A plain click with no drag (e.g. clicking outside every shape
          // to clear the selection) still fires plotly_selected, just with
          // no points -- Plotly doesn't clear its own dimmed/undimmed
          // selection styling for that on its own, so it has to be reset
          // explicitly or the map stays visually stuck on the old
          // selection even though the filter variable is cleared below.
          clearVisualSelection();
          setFilterZipcode(null);
        }
      });

      graphDiv.on('plotly_deselect', function () {
        clearVisualSelection();
        setFilterZipcode(null);
      });

      // Remember the viewer's pan/zoom as they move around, so a later
      // redraw (see currentViewRef above) can restore it instead of
      // resetting to the configured default view. Tracked via both
      // plotly_relayout (fires once, after a pan/zoom/animated button-zoom
      // settles) and plotly_relayouting (fires continuously *during* a
      // drag or an in-progress zoom animation) -- relying on
      // plotly_relayout alone leaves a window, for as long as a zoom
      // animation is still easing, where a data-driven redraw landing
      // then would still see the pre-zoom view and reset back to it
      // before the animation ever gets to finish and report its result.
      function trackCurrentView(relayoutData) {
        const newCenter = relayoutData && relayoutData['map.center'];
        const newZoom = relayoutData && relayoutData['map.zoom'];
        if (newCenter && typeof newZoom === 'number') {
          currentViewRef.current = { lat: newCenter.lat, lon: newCenter.lon, zoom: newZoom };
        }
      }
      graphDiv.on('plotly_relayout', trackCurrentView);
      graphDiv.on('plotly_relayouting', trackCurrentView);

      // Re-scale the heat dots live as the viewer zooms, so each stays
      // roughly confined to its zip instead of bleeding into its neighbors
      // once you're zoomed in past a regional view.
      if (heatmapTraces.length) {
        graphDiv.on('plotly_relayout', function (relayoutData) {
          const newZoom = relayoutData && relayoutData['map.zoom'];
          if (typeof newZoom !== 'number') return;
          const dotSize = 2 * radiusForZoom(baseHeatmapRadius, newZoom);
          const sizes = heatmapFractions.map(fractions => fractions.map(f => f * dotSize));
          Plotly.restyle(graphDiv, { 'marker.size': sizes }, heatmapTraceIndices)
            .then(() => applyHeatDotBlur(graphDiv, heatmapTraceIndices));
        });
      }
    }
    // filterZipcode is intentionally omitted: it's only ever written here
    // (via setFilterZipcode, from the lasso/deselect handlers below), never
    // read. Including it would re-run this whole effect -- tearing down
    // and rebuilding the map -- every time the plugin's own lasso
    // selection writes to it, wiping out the selection that was just
    // made. sigmaData/columns/config are also intentionally omitted in
    // favor of renderTrigger, which only changes once the debounce above
    // settles; this effect still reads their latest values directly
    // (closed over from the current render) once it actually runs. Since
    // useConfig() returns a fresh object every call, leaving config as a
    // direct dependency here would re-run this effect on every render for
    // any reason at all, completely bypassing the debounce.
    // prevSigmaData is likewise omitted even though it's read above -- it's
    // only set here, right before this effect's own content check, so
    // including it would let it "chase" sigmaData and re-fire this whole
    // effect on its own the moment a newer tick lands, independently of
    // (and bypassing) the debounce.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [renderTrigger, heatmapMetricLabel, productLobLabel, setFilterZipcode, zctaByZip]);

  // Zoom in/out via the underlying map (not Plotly.relayout) so the move
  // fires the same relayout event scroll/pinch zoom does -- that's what
  // keeps currentViewRef (and so the next redraw) on the zoomed view.
  const getMap = () => {
    const graphDiv = document.getElementById('myDiv');
    const subplot = graphDiv && graphDiv._fullLayout && graphDiv._fullLayout.map && graphDiv._fullLayout.map._subplot;
    return subplot && subplot.map;
  };

  const zoomBy = direction => {
    const map = getMap();
    if (!map) return;
    if (direction > 0) map.zoomIn();
    else map.zoomOut();
  };

  // Back to the configured view with the lasso tool picked and no zips
  // selected. Unlike zoomBy, the view jumps rather than animates, and
  // currentViewRef is set up front: clearing the filter below refreshes the
  // source, and the redraw that triggers would otherwise restore the old
  // view (or a mid-animation one) right over the reset.
  const resetMap = () => {
    const graphDiv = document.getElementById('myDiv');
    const view = defaultViewRef.current;
    if (!graphDiv || !graphDiv.data || !view) return;

    currentViewRef.current = { ...view };
    dragModeRef.current = 'lasso';
    setDragMode('lasso');
    // selections: [] clears the leftover lasso outline; restyling every
    // trace's selectedpoints to null undoes the dimming of unselected dots.
    Plotly.relayout(graphDiv, {
      'map.center': { lat: view.lat, lon: view.lon },
      'map.zoom': view.zoom,
      dragmode: 'lasso',
      selections: []
    });
    Plotly.restyle(graphDiv, { selectedpoints: graphDiv.data.map(() => null) });
    setFilterZipcode(null);
  };

  const chooseTool = mode => {
    dragModeRef.current = mode;
    setDragMode(mode);
    Plotly.relayout('myDiv', { dragmode: mode });
  };

  return (
    <>
      <div id='myDiv'></div>
      <div className='zoom-controls'>
        <button
          type='button'
          aria-label='Pan'
          title='Pan'
          className={dragMode === 'pan' ? 'active' : ''}
          onClick={() => chooseTool('pan')}
        >
          <svg viewBox='0 0 24 24' width='20' height='20' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
            <path d='M12 3v18M3 12h18M12 3l-3 3M12 3l3 3M12 21l-3-3M12 21l3-3M3 12l3-3M3 12l3 3M21 12l-3-3M21 12l-3 3' />
          </svg>
        </button>
        <button
          type='button'
          aria-label='Lasso select'
          title='Lasso select'
          className={dragMode === 'lasso' ? 'active' : ''}
          onClick={() => chooseTool('lasso')}
        >
          <svg viewBox='0 0 24 24' width='20' height='20' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
            <ellipse cx='12' cy='9' rx='8' ry='5.5' strokeDasharray='3 2.5' />
            <path d='M6.5 13c-1 2 0 4 2 4.5s3-.5 2.5-2' />
          </svg>
        </button>
        <div className='zoom-controls-gap' />
        <button type='button' aria-label='Zoom in' onClick={() => zoomBy(1)}>+</button>
        <button type='button' aria-label='Zoom out' onClick={() => zoomBy(-1)}>&minus;</button>
        <div className='zoom-controls-gap' />
        <button
          type='button'
          aria-label='Reset map'
          title='Reset zoom, pan and selection'
          onClick={resetMap}
        >
          <svg viewBox='0 0 24 24' width='20' height='20' fill='none' stroke='currentColor' strokeWidth='2' strokeLinecap='round' strokeLinejoin='round'>
            <path d='M3 12a9 9 0 1 0 3-6.7' />
            <path d='M3 4v5h5' />
          </svg>
        </button>
      </div>
    </>
  );
}

export default App;
